// @generated by:gauntlet run:godseye-e08-independent-gauntlet

import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type E08ObservabilityFixture,
  e08ObservabilityFixture,
} from "./helpers/e08-observability.js";
import { required } from "./helpers/e08-values.js";

describe("E08 bound telemetry and honest freshness", () => {
  let f: E08ObservabilityFixture;
  beforeEach(async () => {
    f = await e08ObservabilityFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-808 denies an unbound service before storing telemetry", async () => {
    const source = await f.register();
    await expect(
      f.engine.ingest(f.otherService, source.id, f.event(), randomUUID()),
    ).rejects.toThrow();
    expect((await f.engine.logs(f.freshOwner(), {})).records).toHaveLength(0);
  });

  it("T-AC-808 refuses mismatched project environment ancestry at source registration", async () => {
    await expect(
      f.register({
        scope: { projectId: f.secondProject.id, environmentId: f.development.id, resourceId: null },
      }),
    ).rejects.toThrow();
    expect((await f.engine.health(f.freshOwner(), {})).sources).toHaveLength(0);
  });

  it("T-AC-808 keeps telemetry queries and exports behind owner authority", async () => {
    const source = await f.register();
    await f.engine.ingest(f.service, source.id, f.event(), randomUUID());
    await expect(f.engine.logs(f.service, { projectId: f.secondProject.id })).rejects.toThrow();
    await expect(f.engine.metrics(f.service, {})).rejects.toThrow();
    await expect(f.engine.health(f.service, {})).rejects.toThrow();
    await expect(f.engine.timeline(f.service, {})).rejects.toThrow();
  });

  it("T-AC-809 rejects raw prompts and private attributes before durable storage", async () => {
    const source = await f.register();
    const sensitive = "synthetic-private-prompt-not-for-storage";
    await expect(
      f.engine.ingest(
        f.service,
        source.id,
        { ...f.event(), message: sensitive } as ReturnType<typeof f.event>,
        randomUUID(),
      ),
    ).rejects.toThrow();
    await expect(
      f.engine.ingest(
        f.service,
        source.id,
        { ...f.event(), attributes: { authorization: sensitive } } as ReturnType<typeof f.event>,
        randomUUID(),
      ),
    ).rejects.toThrow();
    expect((await f.engine.logs(f.freshOwner(), {})).records).toHaveLength(0);
  });

  it("T-AC-809 gives immutable replay one cursor and paginates monotonically", async () => {
    const source = await f.register(),
      key = randomUUID(),
      event = f.event();
    const first = await f.engine.ingest(f.service, source.id, event, key);
    expect(await f.engine.ingest(f.service, source.id, event, key)).toEqual(first);
    await f.engine.ingest(f.service, source.id, f.event({ code: "SECOND" }), randomUUID());
    const page = await f.engine.logs(f.freshOwner(), { limit: 1 });
    const next = await f.engine.logs(f.freshOwner(), { cursor: page.nextCursor, limit: 1 });
    expect(page.records).toHaveLength(1);
    expect(next.records).toHaveLength(1);
    expect(required(next.records[0]).cursor).toBeGreaterThan(required(page.records[0]).cursor);
    expect(required(next.records[0]).code).toBe("SECOND");
  });

  it("T-AC-809 signals a cursor gap after retention deletes old samples", async () => {
    const source = await f.register();
    await f.engine.ingest(f.service, source.id, f.event(), randomUUID());
    const before = await f.engine.logs(f.freshOwner(), {});
    f.clock.advance((before.retentionDays + 1) * 86_400_000);
    await f.engine.prune(f.freshOwner());
    await f.engine.ingest(f.service, source.id, f.event({ code: "AFTER_RETENTION" }), randomUUID());
    const after = await f.engine.logs(f.freshOwner(), { cursor: 0 });
    expect(after.gap).toBe(true);
    expect(after.records.map((row) => row.code)).toEqual(["AFTER_RETENTION"]);
  });

  it("T-AC-810 distinguishes missing fresh stale and explicit unknown observations", async () => {
    const source = await f.register();
    const state = async () =>
      (await f.engine.health(f.freshOwner(), {})).sources.find(
        (row) => row.source.id === source.id,
      );
    expect(await state()).toMatchObject({
      freshness: "missing",
      observedState: null,
      desiredState: "healthy",
    });
    await f.engine.ingest(f.service, source.id, f.event(), randomUUID());
    expect(await state()).toMatchObject({ freshness: "fresh", observedState: "healthy" });
    f.clock.advance(5_001);
    expect(await state()).toMatchObject({ freshness: "stale", observedState: "healthy" });
    await f.engine.ingest(f.service, source.id, f.event({ state: "unknown" }), randomUUID());
    expect(await state()).toMatchObject({ freshness: "unknown", observedState: "unknown" });
  });

  it("T-AC-810 exposes local observations without inventing remote host health", async () => {
    await f.engine.collect(f.freshOwner());
    const health = await f.engine.health(f.freshOwner(), {});
    const metrics = await f.engine.metrics(f.freshOwner(), {});
    expect(health).toMatchObject({
      remoteHostMetrics: "unavailable",
      externalObserver: "unconfigured",
    });
    expect(metrics.records.flatMap((row) => row.metrics).map((metric) => metric.name)).toContain(
      "process.memory.rss_bytes",
    );
  });
});
